const SECRETS = ["__TIKTOK_SECRET__", "__WEBHOOK_SECRET__"];
const GROCY = "http://grocy-test/api";
const GROCY_KEY = "__GROCY_API_KEY__";
const req = $input.first().json;
const headers = req.headers || {};
if (!SECRETS.includes(headers["x-trigger-secret"])) {
  return [{ json: { ok: false, stop: true, message: "Unauthorized" } }];
}
let url = String((req.body && (req.body.url || req.body.text)) || "").trim();
const m = url.match(/https?:\/\/\S*tiktok\.com\S*/);
if (!m) return [{ json: { ok: false, stop: true, message: "No TikTok link found" } }];
url = m[0];

// Short links (vm.tiktok.com / tiktok.com/t/) redirect to the full video URL
if (!/\/video\/\d+/.test(url)) {
  const res = await this.helpers.httpRequest({ url, method: "GET", returnFullResponse: true,
    ignoreHttpStatusErrors: true, headers: { "User-Agent": "Mozilla/5.0" } });
  const finalUrl = (res.request && res.request.res && res.request.res.responseUrl) || "";
  if (/\/video\/\d+/.test(finalUrl)) url = finalUrl;
}
url = url.split("?")[0];
const videoId = (url.match(/\/video\/(\d+)/) || [])[1] || "";

const oembed = await this.helpers.httpRequest({
  url: "https://www.tiktok.com/oembed?url=" + encodeURIComponent(url), json: true });

if (videoId) {
  const existing = await this.helpers.httpRequest({
    url: GROCY + "/objects/recipes?query%5B%5D=description~" + videoId,
    headers: { "GROCY-API-KEY": GROCY_KEY }, json: true });
  if (existing.length) {
    return [{ json: { ok: true, stop: true, duplicate: true, name: existing[0].name,
      message: "Already imported: " + existing[0].name } }];
  }
}

const caption = oembed.title || "";
const system = [
  "Tu extrais une recette depuis la description d'une vidéo TikTok.",
  "Garde la langue d'origine (souvent le français).",
  "name = le nom du plat (ex: \"Crêpes\", \"Gâteau au chocolat\"), JAMAIS un ingrédient, sans emoji ni hashtag.",
  "N'invente JAMAIS de quantités ni d'ingrédients absents du texte: laisse quantity vide si elle n'est pas donnée.",
  "quantity contient le nombre ET l'unité exactement comme écrits (ex: \"250 g\", \"500 ml\", \"1 càs\", \"4\").",
  "has_recipe = false si le texte ne contient pas de vraie liste d'ingrédients.",
  "diet_flags (en français, un mot court par problème, ex: \"gluten\", \"produits laitiers\", \"oeufs\", \"sucre\"): ce qui pose problème pour ce régime: avoine, sarrasin (anaphylaxie),",
  "oeufs, ananas, colza, sucre (canne ou ajouté), gluten (blé, orge, seigle, épeautre, sauce soja), produits laitiers, sésame, porc.",
].join(" ");

const schema = {
  type: "object", additionalProperties: false,
  required: ["name", "servings", "has_recipe", "ingredients", "steps", "diet_flags"],
  properties: {
    name: { type: "string" },
    servings: { type: ["number", "null"] },
    has_recipe: { type: "boolean" },
    ingredients: { type: "array", items: { type: "object", additionalProperties: false,
      required: ["quantity", "name", "note"],
      properties: { quantity: { type: "string" }, name: { type: "string" }, note: { type: "string" } } } },
    steps: { type: "array", items: { type: "string" } },
    diet_flags: { type: "array", items: { type: "string" } },
  },
};

return [{ json: {
  ok: true, stop: false, url, videoId, caption,
  author: oembed.author_name || "", authorUrl: oembed.author_url || "",
  thumbnailUrl: oembed.thumbnail_url || "",
  llmRequest: {
    models: ["qwen/qwen3.8-27b:free", "nvidia/nemotron-3-super-120b-a12b:free"],
    provider: { require_parameters: true },
    temperature: 0,
    messages: [ { role: "system", content: system }, { role: "user", content: caption } ],
    response_format: { type: "json_schema", json_schema: { name: "recipe", strict: true, schema } },
  },
} }];

const GROCY = "http://grocy-test/api";
const GROCY_KEY = "__GROCY_API_KEY__";
const src = $("Read TikTok").first().json;
const llm = $input.first().json;
// Models sometimes emit half of an emoji pair, which is invalid UTF-8 once stored
const clean = (s) => String(s || "").toWellFormed().replace(/\uFFFD/g, "");
const esc = (s) => clean(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

let r;
try {
  r = JSON.parse(llm.choices[0].message.content);
} catch (e) {
  r = { name: "", servings: null, has_recipe: false, ingredients: [], steps: [], diet_flags: [] };
}
const captionTitle = (src.caption.split(/[#\n]|Ingr/)[0] || "").replace(/[^\p{L}\p{N}' -]/gu, "").trim();
const looksLikeIngredient = r.ingredients.some(i => (i.name || "").toLowerCase() === (r.name || "").toLowerCase().trim());
const title = ((looksLikeIngredient ? "" : r.name) || captionTitle || "Recette TikTok").trim().slice(0, 80);
let name = clean(r.has_recipe ? title : "[À compléter] " + title);
if (r.diet_flags && r.diet_flags.length) name = "⚠️ " + name;

let html = "";
if (r.diet_flags && r.diet_flags.length) {
  html += "<p><strong>⚠️ Attention : " + esc(r.diet_flags.join(", ")) + "</strong></p>";
}
if (r.ingredients.length) {
  html += "<h3>Ingrédients</h3><ul>" + r.ingredients.map(i =>
    "<li>" + esc([i.quantity, i.name].filter(Boolean).join(" ")) + (i.note ? " <em>(" + esc(i.note.replace(/^\(+|\)+$/g, "")) + ")</em>" : "") + "</li>").join("") + "</ul>";
}
if (r.steps.length) {
  html += "<h3>Préparation</h3><ol>" + r.steps.map(s => "<li>" + esc(s) + "</li>").join("") + "</ol>";
}
html += "<h3>Description d'origine</h3><p>" + esc(src.caption).replace(/\n/g, "<br>") + "</p>";
html += '<p>Source : <a href="' + src.url + '">' + esc(src.url) + "</a>" +
        (src.author ? " · " + esc(src.author) : "") + "</p>";

const headers = { "GROCY-API-KEY": GROCY_KEY };
const created = await this.helpers.httpRequest({ method: "POST", url: GROCY + "/objects/recipes", headers, json: true,
  body: { name, description: html, base_servings: r.servings || 1, desired_servings: r.servings || 1 } });
const recipeId = Number(created.created_object_id);

const fileName = "tiktok-" + (src.videoId || recipeId) + ".jpg";
return [{ json: { ok: true, recipeId, name, hasRecipe: r.has_recipe,
  thumbnailUrl: src.thumbnailUrl, fileName, fileNameB64: Buffer.from(fileName).toString("base64"),
  ingredients: r.ingredients.length, steps: r.steps.length, dietFlags: r.diet_flags,
  model: llm.model || "", message: "Recette ajoutée : " + name } }];

const GROCY = "http://grocy-test/api";
const created = $("Create in Grocy").first().json;
const upload = $input.first().json;
const hasImage = !!($("Download thumbnail").first().binary || {}).data;
let photo = false;
if (hasImage && !upload.error) {
  try {
    await this.helpers.httpRequest({ method: "PUT", url: GROCY + "/objects/recipes/" + created.recipeId,
      headers: { "GROCY-API-KEY": "__GROCY_API_KEY__" }, json: true, body: { picture_file_name: created.fileName } });
    photo = true;
  } catch (e) { photo = false; }
}
const { thumbnailUrl, fileName, fileNameB64, ...summary } = created;
return [{ json: { ...summary, photo } }];
